// Simple Fees Explainer Logic
const query = $input.item.json.query || '';
const q = query.toLowerCase();

// Detect scenario
let scenario = 'Expense Ratio';
let clarifiers = [
  'Direct or Regular Plan?',
  'Equity, Debt, or Hybrid?'
];

if (q.includes('elss') || q.includes('exit load')) {
  scenario = 'Exit Load & ELSS';
  clarifiers = [
    'ELSS or non-ELSS fund?',
    'Redeem within 1 year?',
    'Lumpsum or SIP?'
  ];
} else if (q.includes('sip') || q.includes('mandate')) {
  scenario = 'SIP Mandate Fees';
  clarifiers = [
    'Setting up or cancelling?',
    'Which bank?'
  ];
}

// Return clarifiers
return {
  json: {
    status: 'success',
    scenario: scenario,
    questions: clarifiers,
    message: 'Please answer these questions for detailed fee information'
  }
};
